// Dashboard deployment needs one self-contained file; CLI deployment uses the
// original index.ts and shared modules. No environment values enter the bundle.
// Each generated file is parsed before the script finishes, so a duplicated
// top-level name (for example a local copy of a shared helper) fails here and
// not in the Supabase editor ("Identifier has already been declared").
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
const base = 'supabase/functions/';
const shared = name => readFileSync(base + `_shared/${name}.ts`, 'utf8');
const http = shared('http');
const security = shared('counter-security');
const optional = { 'partner-results': shared('partner-results'), 'customer-insights': shared('customer-insights'), 'mercado-pago': shared('mercado-pago') };
const names = ['balcao-api', 'admin-login', 'admin-orders', 'partner-portal', 'partner-register', 'receita-intake', 'customer-signup', 'create-checkout', 'payment-webhook', 'process-payment'];
// Shared modules must stay self-contained: the bundle only concatenates them.
for (const [name, source] of Object.entries({ http, 'counter-security': security, ...optional })) {
  if (/^import\s/m.test(source)) throw new Error(`_shared/${name}.ts must not import other modules (the bundle only concatenates files).`);
}

// Top-level names declared in a file (const/let/var/function/class, with or without export).
const topLevelNames = source => [...source.matchAll(/^(?:export\s+)?(?:async\s+)?(?:const|let|var|function\*?|class)\s+([A-Za-z_$][\w$]*)/gm)].map(match => match[1]);

let esbuild = null;
try { esbuild = await import('esbuild'); } catch { /* Falls back to the duplicate-name scan below. */ }

mkdirSync('supabase/deploy', { recursive: true });
const problems = [];
for (const name of names) {
  const source = readFileSync(base + name + '/index.ts', 'utf8');
  // Imports from ../_shared/ (also when they span several lines) are replaced by the shared code itself.
  const handler = source.replace(/^import\s[^;]*?from '\.\.\/_shared\/[^']+';\r?\n/gm, '');
  if (/from '\.\.\/_shared\//.test(handler)) problems.push(`${name}: import from _shared that the bundle could not inline`);
  const extras = Object.entries(optional).filter(([module]) => source.includes(`_shared/${module}.ts`)).map(([, code]) => code + '\n').join('');
  const bundle = '// Generated by scripts/bundle-counter-function.mjs. Do not edit.\n' + http + '\n' + security + '\n' + extras + handler;
  const declared = topLevelNames(bundle);
  const duplicates = [...new Set(declared.filter((item, index) => declared.indexOf(item) !== index))];
  if (duplicates.length) problems.push(`${name}: duplicated top-level names ${duplicates.join(', ')}`);
  if (esbuild) {
    try { await esbuild.transform(bundle, { loader: 'ts', format: 'esm', target: 'es2022' }); }
    catch (error) { problems.push(`${name}: ${String(error.message || error).split('\n').slice(0, 3).join(' ')}`); }
  }
  writeFileSync(`supabase/deploy/${name}.ts`, bundle);
}
if (problems.length) {
  console.error('Bundle check failed:\n- ' + problems.join('\n- '));
  process.exit(1);
}
console.log(`Prepared self-contained ${names.join(', ')} deployment files (${esbuild ? 'parsed with esbuild' : 'duplicate-name scan only; esbuild not found'}).`);
console.log('process-payment, create-checkout and payment-webhook need "Verify JWT" turned off when published from the dashboard (config.toml only applies to the CLI).');
